<?php
namespace App\Livewire\LMS\SchedulePeriods;
use App\Models\{SchedulePeriod,School}; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\ValidationException; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Livewire\WithPagination; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; use WithPagination; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $name='',$startsAt='',$endsAt='',$sequence='0';
public function mount():void{$this->authorize('viewAny',SchedulePeriod::class);} public function create():void{$this->authorize('create',SchedulePeriod::class);$this->resetForm();$this->showFormModal=true;} public function edit(SchedulePeriod $period):void{$this->authorize('update',$period);$this->editingId=$period->id;$this->name=$period->name;$this->startsAt=$period->starts_at;$this->endsAt=$period->ends_at;$this->sequence=(string)$period->sequence;$this->showFormModal=true;}
public function save():void{$period=$this->editingId?SchedulePeriod::findOrFail($this->editingId):null;$this->authorize($period?'update':'create',$period??SchedulePeriod::class);try{$data=$this->validate(['name'=>['required','string','max:100'],'startsAt'=>['required','date_format:H:i'],'endsAt'=>['required','date_format:H:i','after:startsAt'],'sequence'=>['required','integer','min:0']]);SchedulePeriod::updateOrCreate(['id'=>$period?->id],['school_id'=>School::query()->value('id'),'name'=>$data['name'],'starts_at'=>$data['startsAt'],'ends_at'=>$data['endsAt'],'sequence'=>$data['sequence']]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title($period?'Period updated':'Period added')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save period')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(SchedulePeriod $period):void{$this->authorize('delete',$period);$this->deletingId=$period->id;$this->showDeleteModal=true;} public function delete():void{$period=SchedulePeriod::findOrFail($this->deletingId);$this->authorize('delete',$period);try{$period->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Period deleted')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to delete period')->error()->asToast()->position('top-end')->show();}} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','name','startsAt','endsAt','sequence']);$this->sequence='0';$this->resetValidation();} public function render(){return view('livewire.lms.schedule-periods.index',['periods'=>SchedulePeriod::where('school_id',School::query()->value('id'))->orderBy('sequence')->paginate(15)]);}}
